import { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import { rolColor } from '../utils';
import AccessDenied from '../components/common/AccessDenied';

export default function Utilizatori() {
  const { user } = useAuth();
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const allowed = ['ADMIN_RETEA','MANAGER_JUDET'];

  useEffect(() => {
    if (!allowed.includes(user?.rol)) return setLoading(false);
    api.get('/utilizatori')
      .then(r => setUsers(r.data.data || []))
      .catch(err => setError(err.response?.data?.message || 'Nu am putut încărca utilizatorii.'))
      .finally(() => setLoading(false));
  }, [user?.rol]);

  if (!allowed.includes(user?.rol)) return <AccessDenied message="Doar Admin Rețea și Manager Județ pot accesa această pagină." />;
  if (loading) return <div className="empty-state"><div className="spin">⚕️</div><p>Se încarcă utilizatorii...</p></div>;
  if (error) return <div className="empty-state"><p>{error}</p></div>;

  return (
    <div className="tcard">
      <div className="tcard-head"><h3>👥 Utilizatori & Roluri</h3></div>
      <div style={{ overflowX: 'auto' }}>
        <table className="tbl">
          <thead><tr><th>Email</th><th>Nume</th><th>Rol</th><th>Farmacie</th><th>Activ</th><th>Ultima autentificare</th></tr></thead>
          <tbody>
            {users.length === 0 ? (
              <tr><td colSpan={6} style={{ textAlign: 'center', padding: 20 }}>Nu există utilizatori.</td></tr>
            ) : users.map(user => (
              <tr key={user.id}>
                <td>{user.email}</td>
                <td>{user.nume}</td>
                <td><span className={`badge ${rolColor(user.rol)}`}>{user.rol}</span></td>
                <td>{user.farmacie || '—'}</td>
                <td>{user.activ ? 'Da' : 'Nu'}</td>
                <td>{user.ultima_autentificare ? new Date(user.ultima_autentificare).toLocaleString('ro-RO') : '—'}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
